import { describe, expect, it } from "vitest";
import { parseWireguardConf, providerLabel } from "../src/vpn";

const FILE = `
# generated by the provider
[Interface]
PrivateKey = abc123PrivateKeyabc123PrivateKeyabc123Pr=
Address = 10.2.0.2/32, fd00::2/128   # IPv4 first
DNS = 10.2.0.1

[Peer]
PublicKey = peerPublicKeypeerPublicKeypeerPublicKe=
AllowedIPs = 0.0.0.0/0
Endpoint = 203.0.113.9:51820
`;

describe("parseWireguardConf", () => {
  it("keeps only the key and address for a known provider (the gateway picks the server)", () => {
    const r = parseWireguardConf(FILE, { needsPeer: false });
    expect(r.problems).toEqual([]);
    expect(Object.keys(r.values).sort()).toEqual(["WIREGUARD_ADDRESSES", "WIREGUARD_PRIVATE_KEY"]);
    expect(r.values.WIREGUARD_ADDRESSES).toBe("10.2.0.2/32,fd00::2/128");
  });

  it("also reads the server for 'another provider'", () => {
    const r = parseWireguardConf(FILE, { needsPeer: true });
    expect(r.problems).toEqual([]);
    expect(r.values).toMatchObject({
      WIREGUARD_ENDPOINT_IP: "203.0.113.9",
      WIREGUARD_ENDPOINT_PORT: "51820",
      WIREGUARD_PUBLIC_KEY: "peerPublicKeypeerPublicKeypeerPublicKe=",
    });
  });

  it("ignores comments and blank lines", () => {
    const r = parseWireguardConf("; note\n[Interface]\n# another\nPrivateKey=k\nAddress=10.0.0.2/32\n", {
      needsPeer: false,
    });
    expect(r.values).toEqual({ WIREGUARD_PRIVATE_KEY: "k", WIREGUARD_ADDRESSES: "10.0.0.2/32" });
  });

  it("explains a missing private key in plain words", () => {
    const r = parseWireguardConf("[Interface]\nAddress = 10.0.0.2/32\n", { needsPeer: false });
    expect(r.problems[0]).toMatch(/no private key/);
  });

  it("explains a missing address", () => {
    const r = parseWireguardConf("[Interface]\nPrivateKey = k\n", { needsPeer: false });
    expect(r.problems.join(" ")).toMatch(/no address/);
  });

  it("asks for the server details when 'another provider' is chosen but the file has none", () => {
    const r = parseWireguardConf("[Interface]\nPrivateKey = k\nAddress = 10.0.0.2/32\n", { needsPeer: true });
    expect(r.problems.join(" ")).toMatch(/server details/);
  });

  it("explains a server written as a web address instead of a number", () => {
    const r = parseWireguardConf(FILE.replace("203.0.113.9", "vpn.example.com"), { needsPeer: true });
    expect(r.problems.join(" ")).toMatch(/numeric address/);
  });

  it("treats empty text as having no key", () => {
    expect(parseWireguardConf("", { needsPeer: false }).problems.length).toBeGreaterThan(0);
  });
});

describe("providerLabel", () => {
  it("shows a friendly name and falls back to the id", () => {
    expect(providerLabel("protonvpn")).toBe("Proton VPN");
    expect(providerLabel("private internet access")).toBe("Private Internet Access");
    expect(providerLabel("unknown-vpn")).toBe("unknown-vpn");
    expect(providerLabel(null)).toBe("");
  });
});
